inline ::flatbuffers::Offset<OIL> CreateOIL(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> PROVIDER = 0,
    ::flatbuffers::Offset<::flatbuffers::String> KIND = 0,
    ::flatbuffers::Offset<::flatbuffers::String> LEFT_NAMESPACE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> RIGHT_NAMESPACE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> HEADER = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SHA256 = 0,
    uint64_t BYTES = 0,
    uint32_t ROWS = 0,
    uint32_t DUPLICATE_LINES = 0,
    uint32_t LINK_COUNT = 0,
    uint32_t CLEAN_COUNT = 0,
    uint32_t AMBIGUOUS_COUNT = 0,
    uint32_t LEFT_ID_COUNT = 0,
    uint32_t RIGHT_ID_COUNT = 0,
    uint32_t DATES_DIFFER_COUNT = 0,
    uint32_t UNREADABLE_DATE_COUNT = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<OILLink>>> LINKS = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<OILConflict>>> CONFLICTS = 0,
    int64_t GENERATED_AT_MS = 0) {
  OILBuilder builder_(_fbb);
  builder_.add_GENERATED_AT_MS(GENERATED_AT_MS);
  builder_.add_BYTES(BYTES);
  builder_.add_CONFLICTS(CONFLICTS);
  builder_.add_LINKS(LINKS);
  builder_.add_UNREADABLE_DATE_COUNT(UNREADABLE_DATE_COUNT);
  builder_.add_DATES_DIFFER_COUNT(DATES_DIFFER_COUNT);
  builder_.add_RIGHT_ID_COUNT(RIGHT_ID_COUNT);
  builder_.add_LEFT_ID_COUNT(LEFT_ID_COUNT);
  builder_.add_AMBIGUOUS_COUNT(AMBIGUOUS_COUNT);
  builder_.add_CLEAN_COUNT(CLEAN_COUNT);
  builder_.add_LINK_COUNT(LINK_COUNT);
  builder_.add_DUPLICATE_LINES(DUPLICATE_LINES);
  builder_.add_ROWS(ROWS);
  builder_.add_SHA256(SHA256);
  builder_.add_HEADER(HEADER);
  builder_.add_RIGHT_NAMESPACE(RIGHT_NAMESPACE);
  builder_.add_LEFT_NAMESPACE(LEFT_NAMESPACE);
  builder_.add_KIND(KIND);
  builder_.add_PROVIDER(PROVIDER);
  return builder_.Finish();
}

