inline const OIL *GetOIL(const void *buf) {
  return ::flatbuffers::GetRoot<OIL>(buf);
}

inline const OIL *GetSizePrefixedOIL(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<OIL>(buf);
}

inline const char *OILIdentifier() {
  return "$OIL";
}

inline bool OILBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, OILIdentifier());
}

inline bool SizePrefixedOILBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, OILIdentifier(), true);
}

template <bool B = false>
inline bool VerifyOILBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<OIL>(OILIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedOILBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<OIL>(OILIdentifier());
}

inline void FinishOILBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<OIL> root) {
  fbb.Finish(root, OILIdentifier());
}

inline void FinishSizePrefixedOILBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<OIL> root) {
  fbb.FinishSizePrefixed(root, OILIdentifier());
}

